 const auto stateA=snapshot(store,a),stateB=snapshot(store,b);pa=store.get(a)->parameterState.get();pb=store.get(b)->parameterState.get();
 check(!store.withSessionCollection(entries,[&](const View&){check(!store.increment(a)&&!store.decrement(b)&&!store.removeOnly(a)&&!store.removeAndDelete(b)&&!store.uncacheParameters(a)&&!store.initializeParameters(b)&&!store.evaluateProxies(a),"all targets guarded");check(!store.forward(a,Store::Operation::decrement,true)&&!store.withSessionOverrides(b,{scalar()},[](const auto&){return true;})&&!store.withSessionCollection({entry(a)},[](const auto&){return true;}),"single/group overlap refused");return false;})&&snapshot(store,a)==stateA&&snapshot(store,b)==stateB&&store.get(a)->parameterState.get()==pa&&store.get(b)->parameterState.get()==pb,"guarded observer rollback");
 {auto changed=entries;check(store.withSessionCollection(changed,[&](const View&){changed.clear();return true;}),"input snapshot during observer");}
 {auto*root=store.get(b)->source.get();auto old=root->children[0].text;const auto oldA=snapshot(store,a),oldB=snapshot(store,b);check(!store.withSessionCollection(entries,[&](const View&){root->children[0].text="external edit";return true;})&&snapshot(store,a)==oldA&&snapshot(store,b)==oldB&&root->children[0].text=="external edit","source conflict restores all parameters without erasing explicit edit");root->children[0].text=old;}
 {Store queues;auto one=makeBatch(queues),two=makeBatch(queues,9),other=makeBatch(queues,13);need(queues.forward(one,Store::Operation::decrement,true)&&queues.forward(one,Store::Operation::deleteIfUnreferenced,true),"existing queue");check(queues.withSessionCollection({entry(one),entry(two,22)},[&](const View&){queues.drain();check(queues.queuedCount()==2&&queues.get(one),"no queued target released mid-batch");return queues.withSessionCollection({entry(other,44)},[&](const View&){queues.drain();return queues.queuedCount()==2;});}),"nested disjoint group");queues.drain();check(!queues.get(one)&&queues.get(two)&&queues.queuedCount()==0,"queue drains after all groups");}
 {auto fa=std::make_shared<Factory>(),fb=std::make_shared<Factory>();Store proxies;auto one=makeBatch(proxies,7,false,fa),two=makeBatch(proxies,9,false,fb);std::vector<Entry>input{{one,{scalar()}},{two,{scalar("$alpha",3,0x3f000000)}}};
  auto beforeOne=proxies.get(one)->parameterState.get(),beforeTwo=proxies.get(two)->parameterState.get();check(!proxies.withSessionCollection(input,[&](const View&){check(fa->binding.read()->value.numeric.vector[0]==0x3f400000&&fb->binding.read()->value.numeric.vector[0]==0x3f000000,"both proxy bindings see applied states");return false;})&&proxies.get(one)->parameterState.get()==beforeOne&&proxies.get(two)->parameterState.get()==beforeTwo&&fa->binding.read()->value.text==".25"&&fb->binding.read()->value.text==".25","all proxy bindings rollback before transient destruction");check(proxies.withSessionCollection(input,[](const View&){return true;})&&fa->binding.read()->value.numeric.vector[0]==0x3e800000&&fb->binding.read()->value.numeric.vector[0]==0x3e800000,"proxy restored retargeting");check(proxies.uncacheParameters(one)&&proxies.uncacheParameters(two)&&!fa->binding.valid()&&!fb->binding.valid()&&fa->created==fa->destroyed&&fb->created==fb->destroyed,"proxy retirement balanced");}
 std::cout<<"PASS material_store_batch_checks="<<checks<<" actual_allocation_failures="<<allocationFailures<<" alias_witness_initial=7 applied=22 restored=11 resolved_ids=REQUIRED renderer=NOT_CONNECTED\n";return 0;
