static int batchWire(const char*query,const char*destination){need(!std::ifstream(destination).good(),"fresh batch output");std::ifstream in(query,std::ios::binary);std::ofstream out(destination,std::ios::binary);need(bool(in)&&bool(out),"batch wire IO");auto count=read(in);need(count&&count<10000,"wire cases");put(out,count);
 for(unsigned ci=0;ci<count;++ci){auto n=read(in);need(n<=32,"wire entries");Store store;Store::Id ids[3]={0,makeBatch(store,7),makeBatch(store,9)};std::vector<Entry>input;for(unsigned i=0;i<n;++i){auto target=read(in),bits=read(in);need(target<=2,"wire target");input.push_back(entry(ids[target],bits));}
  put(out,ci);put(out,n);need(store.withSessionCollection(input,[&](const View&v){put(out,integer(store,ids[1]));put(out,integer(store,ids[2]));for(size_t i=0;i<n;++i)put(out,v.backups[i].empty()?0:v.backups[i][0].words[0]);return bool(out);}),"actual store batch");put(out,integer(store,ids[1]));put(out,integer(store,ids[2]));
 }
 need(in.peek()==std::char_traits<char>::eof(),"batch input tail");out.flush();need(bool(out),"batch output");std::cout<<"PASS store_batch_wire_cases="<<count<<'\n';return 0;
}
int main(int argc,char**argv){try{if(argc==1)return batchSafety();if(argc==4&&std::string(argv[1])=="--wire")return batchWire(argv[2],argv[3]);throw std::runtime_error("no args safety OR --wire query fresh-output");}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
